int earliest_eater(int N,long long *A,long long b){
    int l=0,r=N-1,ans=-1;
    while(l<=r){
        int m=(l+r)/2;
        if(A[m]<=b){ ans=m; r=m-1; }
        else l=m+1;
    }
    return ans;
}

void process_all(int N,int M,long long *A,long long *B,int *out){
    for(int i=0;i<M;i++){
        int idx=earliest_eater(N,A,B[i]);
        out[i]= (idx==-1? -1 : idx+1);
    }
}

